function longestRepeat(s: string): string {
  const n = s.length, B = 131, M = 1_000_000_007;
  const code = new Array(n);
  for (let i = 0; i < n; i++) code[i] = s.charCodeAt(i) - 96;

  // start of some repeated window of length L, or -1
  const find = (L: number): number => {
    let pow = 1, h = 0;
    for (let i = 0; i < L; i++) { pow = (pow * B) % M; h = (h * B + code[i]) % M; }
    const seen = new Map<number, number[]>([[h, [0]]]);
    for (let i = 1; i + L <= n; i++) {
      h = ((h * B - (code[i - 1] * pow) % M + M) % M + code[i + L - 1]) % M;
      const list = seen.get(h);
      if (list) {
        const w = s.slice(i, i + L);
        for (const j of list) if (s.slice(j, j + L) === w) return i;
        list.push(i);
      } else seen.set(h, [i]);
    }
    return -1;
  };

  let lo = 1, hi = n - 1, bestStart = -1, bestLen = 0;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    const at = find(mid);
    if (at >= 0) { bestStart = at; bestLen = mid; lo = mid + 1; }
    else hi = mid - 1;
  }
  return bestStart < 0 ? "" : s.slice(bestStart, bestStart + bestLen);
}

