            seen = {h: [0]}
            for i in range(1, n - L + 1):
                h = (h * B - code[i - 1] * pow_l + code[i + L - 1]) % M
                if h in seen:
                    w = s[i:i + L]
                    if any(s[j:j + L] == w for j in seen[h]):
                        return i
                    seen[h].append(i)
                else:
                    seen[h] = [i]
            return -1

        lo, hi, best_start, best_len = 1, n - 1, -1, 0
        while lo <= hi:
            mid = (lo + hi) // 2
            at = find(mid)
